import { normalizeDomain } from "@/lib/normalizeDomain"

/**
 * Google's disavow file format (https://support.google.com/webmasters/answer/2648487): plain text, one entry per line, "#" starts a comment,
 * "domain:example.com" disavows a whole domain. PURE.
 *
 *   # Disavow file for example.com — generated by Odito on 2026-10-28
 *   domain:spam-one.com
 *   domain:spam-two.net
 *
 * Every entry is cleaned with the shared normalizeDomain, an unusable one is dropped (a malformed line could make Google reject the whole
 * file), and repeats are removed. The order is the order of the list given.
 */

/** "YYYY-MM-DD" in UTC. */
const isoDay = (date) => date.toISOString().slice(0, 10)

/**
 * @param {string[]} domains the project's disavowed domains
 * @param {{ target?: string, now?: Date }} [options] target = the project's own domain (for the comment line)
 * @returns {{ text: string, count: number, skipped: string[] }} `skipped` = entries that were not valid domains
 */
export function buildDisavowFile(domains, { target = "", now = new Date() } = {}) {
  const seen = new Set()
  const skipped = []
  const lines = []
  for (const raw of Array.isArray(domains) ? domains : []) {
    const clean = normalizeDomain(raw)
    if (!clean) { skipped.push(String(raw)); continue }
    if (seen.has(clean)) continue
    seen.add(clean)
    lines.push(`domain:${clean}`)
  }
  const site = normalizeDomain(target) || "your site"
  const header = `# Disavow file for ${site} — generated by Odito on ${isoDay(now)}`
  return { text: `${[header, ...lines].join("\n")}\n`, count: lines.length, skipped }
}

/** disavow_<domain>_<YYYY-MM-DD>.txt */
export function disavowFileName(target, now = new Date()) {
  const safe = String(normalizeDomain(target) || "domain").replace(/[^a-z0-9.-]/gi, "-")
  return `disavow_${safe}_${isoDay(now)}.txt`
}

/** What the confirmation says before the file is downloaded. */
export const DISAVOW_WARNING = "Only disavow domains you are sure are harmful. Upload this file in Google Search Console's Disavow Links tool."
